mapper.update:
UPDATE flash_usage SET status = 'used', order_id = NULL
WHERE user_id = #{userId} AND product_id = #{productId} AND flash_day = #{day}
  AND status = 'released'

UPDATE flash_usage SET order_id = #{orderId}
WHERE user_id = #{userId} AND product_id = #{productId} AND flash_day = #{day}
  AND status = 'used'

mapper.select:
SELECT COUNT(*) FROM flash_usage
WHERE user_id = #{userId} AND product_id = #{productId} AND flash_day = #{day}
  AND status = 'used'
